const std = @import("std");
const allocator = std.heap.page_allocator;

const Box = struct {
    v: i32,
};

const Holder = struct {
    child: ?*Box,
};

pub fn main() void {
    const h = Holder{ .child = allocator.create(Box) catch null };
    if (h.child) |p| allocator.destroy(p);
    if (h.child) |p| allocator.destroy(p);
}

